def comps4(g,bg):
    Hh,Ww=len(g),len(g[0]); seen=[[False]*Ww for _ in range(Hh)]; out=[]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<Hh and 0<=nx<Ww and not seen[ny][nx] and g[ny][nx]==g[y][x]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append((g[i][j],cells))
    return out

def bar_len(shape):
    # max straight run in any of the four directions through same-color cells (contiguous)
    s=set(shape); best=0
    for dy,dx in ((0,1),(1,0),(1,1),(1,-1)):
        cur=None; n=0
        for p in sorted(s,key=lambda t:t[0]*dy+t[1]*dx):
            if cur and (p[0]-cur[0])==dy and (p[1]-cur[1])==dx: n+=1
            else: n=1
            best=max(best,n); cur=p
    return best

