def diag_adj(cells):
    cells=list(cells); n=len(cells); cnt=0
    for i in range(n):
        for j in range(i+1,n):
            a,b=cells[i]; c2,d2=cells[j]
            if abs(a-c2)==1 and abs(b-d2)==1: cnt+=1
    return max(cnt,1)

